def record_audit_event(actor, action, target, outcome, acting_for=None, extra=None):
    entry = {
        "timestamp": utc_now_iso(),
        "actor": actor,
        "acting_for": acting_for,
        "action": action,
        "target": target,
        "outcome": outcome,
        "request_id": current_request_id(),
    }
    if extra:
        entry.update(extra)
    audit_store.append(entry)   # append only, never update or delete

def summarize_arguments(tool_name, args):
    if tool_name == "get_customer_record":
        return f"customer_id={args['customer_id']}"   # never log the full record
    return "arguments redacted"

